/**
 * Text forms of efa2 field values, as written by efa2 2.5 (checked on a
 * project generated by efa itself):
 * dates "dd.MM.yyyy", times "HH:mm:ss", distances "12.5 km" / "6000 m",
 * lists joined by ";" with "~" for an empty item, booleans only written
 * when true, timestamps in epoch milliseconds.
 */

/** efa2's "valid forever" marker (Long.MAX_VALUE). */
export const EFA2_FOREVER = "9223372036854775807";

const pad = (value: number, length = 2) => String(value).padStart(length, "0");

/** "08.03.2025" → "2025-03-08". Partial dates ("03/2025", "2025") are completed with the 1st. */
export const efaDateToIso = (value: string | undefined): string | null => {
  if (!value) return null;
  const text = value.trim();
  let match = /^(\d{1,2})\.(\d{1,2})\.(\d{4})$/.exec(text);
  if (match) {
    return `${match[3]}-${pad(Number(match[2]))}-${pad(Number(match[1]))}`;
  }
  match = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(text);
  if (match) {
    return `${match[3]}-${pad(Number(match[1]))}-${pad(Number(match[2]))}`;
  }
  match = /^(\d{1,2})[./](\d{4})$/.exec(text);
  if (match) {
    return `${match[2]}-${pad(Number(match[1]))}-01`;
  }
  match = /^(\d{4})$/.exec(text);
  if (match) {
    return `${match[1]}-01-01`;
  }
  return null;
};

/** "2025-03-08" (or a longer ISO string) → "08.03.2025". */
export const isoToEfaDate = (
  value: string | null | undefined
): string | undefined => {
  if (!value) return undefined;
  const match = /^(\d{4})-(\d{2})-(\d{2})/.exec(value);
  return match ? `${match[3]}.${match[2]}.${match[1]}` : undefined;
};

/** "14:45:00" → "14:45". */
export const efaTimeToHhMm = (value: string | undefined): string | null => {
  if (!value) return null;
  const match = /^(\d{1,2}):(\d{2})/.exec(value.trim());
  return match ? `${pad(Number(match[1]))}:${match[2]}` : null;
};

/** "2025-03-08T14:45" → "14:45:00". */
export const localDateTimeToEfaTime = (value: string | null | undefined) => {
  const match = value ? /T(\d{2}):(\d{2})/.exec(value) : null;
  return match ? `${match[1]}:${match[2]}:00` : undefined;
};

const UNIT_TO_METRES: Record<string, number> = {
  km: 1000,
  m: 1,
  mi: 1609.344,
  yd: 0.9144,
};

/** "12.5 km" → 12500 m. A bare number is in km. */
export const efaDistanceToMetres = (
  value: string | undefined
): number | null => {
  if (!value) return null;
  const match = /^\s*(-?\d+(?:[.,]\d+)?)\s*([a-z]*)\s*$/i.exec(value);
  if (!match) return null;
  const amount = Number(match[1].replace(",", "."));
  const factor = UNIT_TO_METRES[match[2].toLowerCase() || "km"];
  if (!Number.isFinite(amount) || factor === undefined) return null;
  return Math.round(amount * factor);
};

/** 12500 → "12.5 km". */
export const metresToEfaDistance = (metres: number | null | undefined) => {
  if (metres === null || metres === undefined) return undefined;
  const kilometres = Math.round(metres) / 1000;
  return `${kilometres} km`;
};

export const efaList = (value: string | undefined): string[] =>
  value === undefined || value === ""
    ? []
    : value.split(";").map((item) => (item === "~" ? "" : item));

/** List items cannot contain ";" in efa2: it would split them on the next read. */
export const toEfaList = (items: (string | null | undefined)[]) =>
  items
    .map((item) =>
      item === null || item === undefined || item === ""
        ? "~"
        : item.replace(/;/g, ",")
    )
    .join(";");

export const efaBoolean = (value: string | undefined) => value === "true";

/** Only true is written, as efa2 does. */
export const toEfaBoolean = (value: boolean | null | undefined) =>
  value ? "true" : undefined;

/** Epoch milliseconds as text → Date, or null for "forever" and junk. */
export const efaTimestamp = (value: string | undefined): number | null => {
  if (!value || value === EFA2_FOREVER) return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
};
